ContractedCompositionsIndependentReview.full_child_product_transported.{u_1} {n : ℕ} [NeZero n] {R : Type u_1}
  [CommMonoid R] (t : SM.IncreasingBoundaryTriple n) {J : SM.BoundaryInterval t.contractedSize}
  (π : SM.IntervalComposition J) (X : SM.IntervalArray n R) :
  ∏ k, X ((SM.IntervalComposition.expandComposition t π).part k) = ∏ k, X (t.expandInterval (π.part k))

ContractedCompositionsIndependentReview.full_nearfar_weight_transported.{u_1} {n : ℕ} [NeZero n] {R : Type u_1}
  [CommRing R] [Invertible 2] (t : SM.IncreasingBoundaryTriple n) {J : SM.BoundaryInterval t.contractedSize}
  (π : SM.IntervalComposition J) (D H : SM.TripleArray n R) :
  (SM.IntervalComposition.expandComposition t π).nearFarWeight D H =
    π.nearFarWeight (fun u => D (t.expandTriple u)) fun u => H (t.expandTriple u)
